styles.h1:
font-size: 28px;
color: #00f2fe;
margin-bottom: 15px;
letter-spacing: 0.5px;
font-weight: 600;
position: relative;
text-align: center;

styles.h2:
font-size: 16px;
color: rgba(255, 255, 255, 0.8);
margin-bottom: 24px;
font-weight: 400;
letter-spacing: 0.5px;
text-align: center;
position: relative;

styles.h3:
display: block;
color: #00f2fe;
margin-bottom: 6px;
font-size: 16px;
font-weight: 600;
letter-spacing: 0.5px;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #4facfe;
text-decoration: none;
border-bottom: 1px dashed rgba(79, 172, 254, 0.5);
transition: all 0.3s ease;
position: relative;

styles.ul:
padding-left: 0;
display: grid;
grid-template-columns: repeat(2, 1fr);
gap: 15px;
margin: 20px 0;

styles.li:
position: relative;


margin-bottom: 16px;
padding-left: 40px;
color: rgba(255, 255, 255, 0.85);
line-height: 1.6;
font-size: 15px;

styles.blockquote:
background: rgba(0, 0, 0, 0.1);
border-left: 3px solid #4facfe;
color: rgba(255, 255, 255, 0.8);
padding: 15px 20px;
margin: 20px 0;
font-style: italic;
position: relative;
border-radius: 0 8px 8px 0;
backdrop-filter: blur(5px);
-webkit-backdrop-filter: blur(5px);

styles.pre:
background: rgba(0, 0, 0, 0.2) !important;
border: 1px solid rgba(255, 255, 255, 0.18);
border-radius: 8px;
padding: 16px;
margin: 20px 0;
overflow-x: auto;
position: relative;
backdrop-filter: blur(5px);
-webkit-backdrop-filter: blur(5px);

styles.hr:
border: 0;
height: 1px;
background: linear-gradient(
  90deg,
  transparent,
  rgba(79, 172, 254, 0.5),
  transparent
);
margin: 25px 0;

styles.img:
max-width: 100%;
border: 1px solid rgba(255, 255, 255, 0.2);
border-radius: 8px;
box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
margin: 20px 0;
backdrop-filter: blur(5px);
-webkit-backdrop-filter: blur(5px);

styles.table:
width: 100%;
border-collapse: collapse;
margin: 20px 0;
background: rgba(255, 255, 255, 0.1);
border-radius: 8px;
overflow: hidden;
backdrop-filter: blur(5px);
-webkit-backdrop-filter: blur(5px);
border: 1px solid rgba(255, 255, 255, 0.2);

styles.th:
background: rgba(79, 172, 254, 0.2);
color: rgba(255, 255, 255, 0.9);
border-bottom: 1px solid rgba(255, 255, 255, 0.2);
padding: 12px;
font-weight: 600;
text-align: left;

styles.td:
color: rgba(255, 255, 255, 0.8);
padding: 12px;
border-bottom: 1px solid rgba(255, 255, 255, 0.1);
